// Writes the redirect-stub site that GitHub Pages serves after the move to https://lumamatters.lumalux.at/.
// Usage: npm run sync && node scripts/make-redirects.mjs [outDir]   (default: redirects-dist)
// Slugs come from src/content/docs (generated by `npm run sync`), so new manual pages are covered automatically.
import { readdirSync, mkdirSync, writeFileSync, rmSync, existsSync } from 'node:fs';
import { join, dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const out = resolve(process.argv[2] ?? join(root, 'redirects-dist'));
const docs = join(root, 'src', 'content', 'docs');
const NEW = 'https://lumamatters.lumalux.at';

if (!existsSync(docs)) {
  console.error('make-redirects: src/content/docs missing, run `npm run sync` first');
  process.exit(1);
}
const slugs = readdirSync(docs)
  .filter((f) => f.endsWith('.md') && f !== 'index.md')
  .map((f) => f.slice(0, -3));
if (slugs.length === 0) {
  console.error('make-redirects: no pages found in src/content/docs');
  process.exit(1);
}

const stub = (target) => `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Moved - LUMAMATTERS</title>
<meta name="robots" content="noindex">
<link rel="canonical" href="${target}">
<meta http-equiv="refresh" content="0; url=${target}">
<script>location.replace(${JSON.stringify(target)} + location.search + location.hash);</script>
</head>
<body>
<p>This page moved to <a href="${target}">${target}</a>.</p>
</body>
</html>
`;

rmSync(out, { recursive: true, force: true });
let count = 0;
const write = (relPath, target) => {
  const file = join(out, relPath);
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, stub(target));
  count++;
};

// Manual home, old root and old /manual/ prefix.
write('index.html', `${NEW}/manual/`);
write('manual/index.html', `${NEW}/manual/`);
for (const s of slugs) {
  write(`${s}/index.html`, `${NEW}/manual/${s}/`);
  write(`manual/${s}/index.html`, `${NEW}/manual/${s}/`);
}
// Demo and legal pages.
write('demo/index.html', `${NEW}/demo/`);
write('impressum.html', `${NEW}/impressum.html`);
write('privacy.html', `${NEW}/privacy.html`);

// GitHub Pages serves 404.html for every unknown path (for example /demo/assets/x.js, old anchors, typos):
// keep the path for /demo/ and /manual/, send everything else to the manual home.
writeFileSync(
  join(out, '404.html'),
  `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Moved - LUMAMATTERS</title>
<meta name="robots" content="noindex">
<meta http-equiv="refresh" content="0; url=${NEW}/">
<script>
(function () {
  var p = location.pathname.replace(/^\/LUMAMATTERS-manual/, '') || '/';
  var t = /^\/(demo|manual)(\/|$)/.test(p) ? p : '/manual' + (p === '/' ? '/' : p);
  location.replace(${JSON.stringify(NEW)} + t + location.search + location.hash);
})();
</script>
</head>
<body>
<p>This site moved to <a href="${NEW}/">${NEW}/</a>.</p>
</body>
</html>
`,
);
writeFileSync(join(out, '.nojekyll'), '');
console.log(`make-redirects: ${count} stubs + 404.html written to ${out}`);
